const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Ticket_ID",
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Issue",
  "Priority",
  "Assigned_Team",
  "Created_At"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const validPriorities = [
    "Critical",
    "High",
    "Medium",
    "Low"
  ];

  const priorityValid =
    validPriorities.some(
      p =>
        p.toLowerCase() ===
        String(data.Priority).toLowerCase()
    );

  const createdDate =
    new Date(data.Created_At);

  const dateValid =
    !isNaN(createdDate.getTime());

  if (
    missingFields.length === 0 &&
    priorityValid &&
    dateValid
  ) {

    validItems.push({
      ...data
    });

  } else {

    invalidItems.push({
      ticket_id:
        data.Ticket_ID || "Unknown",

      missing_fields:
        missingFields
    });
  }
}

return [
  {
    json: {
      data_valid:
        invalidItems.length === 0,

      total_tickets:
        items.length,

      valid_tickets:
        validItems.length,

      invalid_tickets:
        invalidItems.length,

      invalid_details:
        invalidItems,

      ticket_data:
        validItems
    }
  }
];

const tickets = $json.ticket_data;

const now = new Date();

const slaRules = {
  critical: 4,
  high: 8,
  medium: 24,
  low: 48
};

const results = [];

for (const ticket of tickets) {

  const priority =
    String(ticket.Priority).toLowerCase();

  const createdAt =
    new Date(ticket.Created_At);

  const elapsedMilliseconds =
    now.getTime() - createdAt.getTime();

  const elapsedHours =
    elapsedMilliseconds / (1000 * 60 * 60);

  const slaHours =
    slaRules[priority];

  if (!slaHours) {
    continue;
  }

  const remainingHours =
    slaHours - elapsedHours;

  const riskThreshold =
    slaHours * 0.20;

  let slaStatus;

  if (remainingHours <= 0) {

    slaStatus = "BREACHED";

  } else if (remainingHours <= riskThreshold) {

    slaStatus = "AT RISK";

  } else {

    slaStatus = "ON TRACK";
  }

  results.push({

    ...ticket,

    SLA_Hours:
      Number(slaHours.toFixed(2)),

    Elapsed_Hours:
      Number(Math.max(elapsedHours, 0).toFixed(2)),

    Remaining_Hours:
      Number(Math.max(remainingHours, 0).toFixed(2)),

    SLA_Status:
      slaStatus
  });
}

return [
  {
    json: {
      sla_tickets:
        results
    }
  }
];

